from google.cloud import translate_v2 as translate
import os

def ocr_translate(text: str, target_language: str, config=None):
    config = config or {}
    translate_client = translate.Client()

    result = translate_client.translate(text, target_language=target_language)

    return {"translated_text": result["translatedText"], "detected_source_language": result["detectedSourceLanguage"]}

from google.cloud import language_v1
from google.cloud.language_v1 import enums
import os

def ocr_safety(text: str, config=None):
    config = config or {}
    client = language_v1.LanguageServiceClient()

    document = language_v1.Document(content=text, type=enums.Document.Type.PLAIN_TEXT)

    # Available categories: https://cloud.google.com/natural-language/docs/reference/rest/v1/documents/analyzeContent
    response = client.classify_text(document=document)

    categories = []
    for category in response.categories:
        categories.append({"name": category.name, "confidence": category.confidence})

    return {"safety_attributes": categories}

from document_client import DocumentClient
from document_models import DocumentPayload, ExtractionResult
import os

def document_field_extraction(payload: DocumentPayload, config=None):
    config = config or {}
    region = config.get("region", os.environ.get("AWS_REGION", "us-east-1"))
    client_wrapper = DocumentClient(region_name=region)
    client = client_wrapper.get_textract_client()

    response = client.analyze_document(
        Document={
            "Bytes": payload.document_bytes
        },
        FeatureTypes=["FORMS"]
    )

    key_value_pairs = {}
    key_map = {}
    value_map = {}
    block_map = {block["Id"]: block for block in response["Blocks"]}

    for block in response["Blocks"]:
        if block["BlockType"] == "KEY_VALUE_SET":
            if "KEY" in block["EntityTypes"]:
                key_map[block["Id"]] = block
            else:
                value_map[block["Id"]] = block

    for block_id, key_block in key_map.items():
        value_block = None
        for relationship in key_block["Relationships"]:
            if relationship["Type"] == "VALUE":
                for value_id in relationship["Ids"]:
                    if value_id in value_map:
                        value_block = value_map[value_id]
                        break

        key_text = "".join([block_map[bid]["Text"] for bid in key_block["Relationships"][0]["Ids"] if block_map[bid]["BlockType"] == "WORD"])
        value_text = "" 
        if value_block:
            value_text = "".join([block_map[bid]["Text"] for bid in value_block["Relationships"][0]["Ids"] if block_map[bid]["BlockType"] == "WORD"])

        key_value_pairs[key_text] = value_text

    return ExtractionResult({"extracted_fields": key_value_pairs}).data
